    private ActionResult<string> ResolveTenant(string? tenant, string? tenantId)
    {
        const string tenantSource = "System";
        if (string.Equals(tenantSource, "System", StringComparison.Ordinal))
        {
            return "system";
        }

        if (string.Equals(tenantSource, "Route", StringComparison.Ordinal))
        {
            string? normalizedTenant = string.IsNullOrWhiteSpace(tenant) ? null : tenant;
            string? normalizedTenantId = string.IsNullOrWhiteSpace(tenantId) ? null : tenantId;
            if (normalizedTenant is not null
                && normalizedTenantId is not null
                && !string.Equals(normalizedTenant, normalizedTenantId, StringComparison.Ordinal))
            {
                return CreateProblem(StatusCodes.Status400BadRequest, "Bad Request", "Tenant route values differ.");
            }

            string? resolvedTenant = normalizedTenant ?? normalizedTenantId;
            return string.IsNullOrWhiteSpace(resolvedTenant)
                ? CreateProblem(StatusCodes.Status400BadRequest, "Bad Request", "Tenant route value is required.")
                : resolvedTenant;
        }

        string[] tenants = User.FindAll("eventstore:tenant")
            .Select(static claim => claim.Value)
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (tenants.Length == 0)
        {
            return CreateProblem(StatusCodes.Status403Forbidden, "Forbidden", "A tenant claim is required.");
        }

        return tenants.Length == 1
            ? tenants[0]
            : CreateProblem(StatusCodes.Status400BadRequest, "Bad Request", "The tenant is ambiguous.");
    }

    private void AppendQueryMetadataHeaders(QueryResponseMetadata? metadata)
    {
        Response.Headers.Remove(ProjectionLifecyclePolicy.HeaderName);
        QueryResponseProvenance provenance = metadata?.Provenance ?? QueryResponseProvenance.Unknown;
        Response.Headers["X-Hexalith-Query-Provenance"] = GetCanonicalQueryProvenanceName(provenance);

        if (metadata is null)
        {
            return;
        }

        if (provenance == QueryResponseProvenance.ProjectionBacked
            && TryGetBoundedHeaderValue(metadata.ProjectionVersion, out string? projectionVersion))
        {
            Response.Headers["X-Hexalith-Projection-Version"] = projectionVersion;
        }

        ProjectionLifecycleState lifecycle = ProjectionLifecyclePolicy.Normalize(metadata.Lifecycle, provenance);
        bool? isStale = ProjectionLifecyclePolicy.ProjectIsStale(lifecycle, metadata.IsStale);
        bool? isDegraded = ProjectionLifecyclePolicy.ProjectIsDegraded(lifecycle, metadata.IsDegraded);
        if (lifecycle != ProjectionLifecycleState.Unknown)
        {
            Response.Headers[ProjectionLifecyclePolicy.HeaderName] = GetCanonicalProjectionLifecycleName(lifecycle);
        }

        if (metadata.ServedAt is not null)
        {
            Response.Headers["X-Hexalith-Served-At"] = metadata.ServedAt.Value.ToString("O", CultureInfo.InvariantCulture);
        }

        if (provenance == QueryResponseProvenance.ProjectionBacked && isStale is not null)
        {
            Response.Headers["X-Hexalith-Is-Stale"] = isStale.Value ? "true" : "false";
        }

        if (isDegraded is not null)
        {
            Response.Headers["X-Hexalith-Is-Degraded"] = isDegraded.Value ? "true" : "false";
        }

        if (TryFormatWarningCodes(metadata.WarningCodes, out string? warningCodes))
        {
            Response.Headers["X-Hexalith-Warning-Codes"] = warningCodes;
        }

        QueryPagingMetadata? paging = metadata.Paging;
        if (paging is null)
        {
            return;
        }

        if (paging.PageSize > 0 && paging.PageSize <= QueryPolicyLimits.MaxPageSize)
        {
            Response.Headers["X-Hexalith-Page-Size"] = paging.PageSize.ToString(CultureInfo.InvariantCulture);
        }

        if (paging.Offset.HasValue && paging.Offset.Value >= 0)
        {
            Response.Headers["X-Hexalith-Page-Offset"] = paging.Offset.Value.ToString(CultureInfo.InvariantCulture);
        }

        if (paging.TotalCount.HasValue && paging.TotalCount.Value >= 0)
        {
            Response.Headers["X-Hexalith-Page-Total-Count"] = paging.TotalCount.Value.ToString(CultureInfo.InvariantCulture);
        }

        if (paging.HasMore is not null)
        {
            Response.Headers["X-Hexalith-Page-Has-More"] = paging.HasMore.Value ? "true" : "false";
        }

        if (TryGetBoundedHeaderValue(paging.NextCursor, out string? nextCursor))
        {
            Response.Headers["X-Hexalith-Next-Cursor"] = nextCursor;
        }
    }

    private static string GetCanonicalQueryProvenanceName(QueryResponseProvenance provenance)
        => provenance switch
        {
            QueryResponseProvenance.ProjectionBacked => nameof(QueryResponseProvenance.ProjectionBacked),
            QueryResponseProvenance.HandlerComputed => nameof(QueryResponseProvenance.HandlerComputed),
            _ => nameof(QueryResponseProvenance.Unknown),
        };

    private static string GetCanonicalProjectionLifecycleName(ProjectionLifecycleState lifecycle)
        => lifecycle switch
        {
            ProjectionLifecycleState.Current => nameof(ProjectionLifecycleState.Current),
            ProjectionLifecycleState.Stale => nameof(ProjectionLifecycleState.Stale),
            ProjectionLifecycleState.Rebuilding => nameof(ProjectionLifecycleState.Rebuilding),
            ProjectionLifecycleState.Degraded => nameof(ProjectionLifecycleState.Degraded),
            ProjectionLifecycleState.Unavailable => nameof(ProjectionLifecycleState.Unavailable),
            ProjectionLifecycleState.LocalOnly => nameof(ProjectionLifecycleState.LocalOnly),
            _ => nameof(ProjectionLifecycleState.Unknown),
        };

    private static bool TryFormatWarningCodes(IReadOnlyList<string>? warningCodes, out string? headerValue)
    {
        headerValue = null;
        if (warningCodes is null || warningCodes.Count == 0 || warningCodes.Count > MaxWarningCodeCount)
        {
            return false;
        }

        var boundedCodes = new List<string>(warningCodes.Count);
        foreach (string warningCode in warningCodes)
        {
            if (!TryGetBoundedHeaderValue(warningCode, out string? boundedCode))
            {
                return false;
            }

            if (!IsWarningCodeToken(boundedCode))
            {
                return false;
            }

            boundedCodes.Add(boundedCode);
        }

        string value = string.Join(",", boundedCodes);
        if (value.Length > MaxHeaderValueLength)
        {
            return false;
        }

        headerValue = value;
        return true;
    }

    private static bool TryGetBoundedHeaderValue(string? value, [NotNullWhen(true)] out string? headerValue)
    {
        headerValue = null;
        if (string.IsNullOrWhiteSpace(value))
        {
            return false;
        }

        if (value.Length == 0 || value.Length > MaxHeaderValueLength)
        {
            return false;
        }

        if (ContainsHeaderControlCharacter(value))
        {
            return false;
        }

        headerValue = value;
        return true;
    }

    private static bool IsWarningCodeToken(string value)
    {
        foreach (char character in value)
        {
            bool isAsciiLetter = character is >= 'A' and <= 'Z' or >= 'a' and <= 'z';
            bool isAsciiDigit = character is >= '0' and <= '9';
            if (!isAsciiLetter && !isAsciiDigit && character != '-' && character != '_' && character != '.')
            {
                return false;
            }
        }

        return true;
    }

    private static bool ContainsHeaderControlCharacter(string value)
    {
        foreach (char character in value)
        {
            if (char.IsControl(character))
            {
                return true;
            }
        }

        return false;
    }

    private ObjectResult MapGatewayException(EventStoreGatewayException exception, bool includeCommandOnlyStatusCodes)
    {
        int statusCode = NormalizeGatewayExceptionStatusCode(exception.StatusCode, includeCommandOnlyStatusCodes);
        if (IsRetryableGatewayStatusCode(statusCode) && TryGetSafeRetryAfterHeaderValue(exception.RetryAfter, out string? retryAfter))
        {
            Response.Headers["Retry-After"] = retryAfter;
        }

        var problem = new ProblemDetails
        {
            Status = statusCode,
            Title = GetSafeProblemDisplayText(exception.Title) ?? "Gateway Error",
            Type = GetSafeProblemDisplayText(exception.Type) ?? "about:blank",
            Detail = GetSafeProblemDisplayText(exception.Detail),
        };

        AddSafeProblemTokenExtension(problem, "correlationId", exception.CorrelationId);
        AddSafeProblemTokenExtension(problem, "tenantId", exception.TenantId);
        AddSafeProblemTokenExtension(problem, "reason", exception.Reason);
        AddSafeProblemTokenExtension(problem, "reasonCode", exception.ReasonCode);
        IReadOnlyDictionary<string, string> __hexalithSafeErrors = FilterSafeErrors(exception.Errors);
        if (__hexalithSafeErrors.Count > 0)
        {
            problem.Extensions["errors"] = __hexalithSafeErrors;
        }

        return new ObjectResult(problem)
        {
            StatusCode = problem.Status,
            ContentTypes = { "application/problem+json" },
        };
    }

    private static ObjectResult CreateProblem(int statusCode, string title, string detail)
    {
        var problem = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Type = "about:blank",
            Detail = detail,
        };

        return new ObjectResult(problem)
        {
            StatusCode = statusCode,
            ContentTypes = { "application/problem+json" },
        };
    }

    private static void AddSafeProblemTokenExtension(ProblemDetails problem, string key, string? value)
    {
        if (TryGetBoundedHeaderValue(value, out string? token) && IsWarningCodeToken(token))
        {
            problem.Extensions[key] = token;
        }
    }

    private static string? GetSafeProblemDisplayText(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)
            || value.Length > MaxHeaderValueLength
            || ContainsHeaderControlCharacter(value))
        {
            return null;
        }

        return value.IndexOf("authorization", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("bear" + "er", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("cursor", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("etag", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("jwt", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("password", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("payload", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("secret", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("stack", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("token", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("trace", StringComparison.OrdinalIgnoreCase) < 0
            ? value
            : null;
    }

    private static IReadOnlyDictionary<string, string> FilterSafeErrors(IReadOnlyDictionary<string, string> errors)
    {
        var safeErrors = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (KeyValuePair<string, string> error in errors)
        {
            if (safeErrors.Count >= MaxProblemErrorCount)
            {
                break;
            }

            if (IsSupportSafeProblemText(error.Key) && IsSupportSafeProblemText(error.Value))
            {
                safeErrors[error.Key] = error.Value;
            }
        }

        return safeErrors;
    }

    private static bool IsSupportSafeProblemText(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)
            || value.Length > MaxHeaderValueLength
            || ContainsHeaderControlCharacter(value))
        {
            return false;
        }

        return value.IndexOf("authorization", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("bear" + "er", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("cursor", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("etag", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("jwt", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("password", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("payload", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("secret", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("stack", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("token", StringComparison.OrdinalIgnoreCase) < 0
            && value.IndexOf("trace", StringComparison.OrdinalIgnoreCase) < 0;
    }

    private static bool TryFormatStrongETag(string etag, [NotNullWhen(true)] out string? headerValue)
    {
        headerValue = null;
        if (!string.Equals(etag, etag.Trim(), StringComparison.Ordinal))
        {
            return false;
        }

        string value = etag.Trim();
        if (!TryGetBoundedHeaderValue(value, out string? boundedValue))
        {
            return false;
        }

        if (ContainsWhitespace(boundedValue))
        {
            return false;
        }

        string candidate = boundedValue.Length >= 2 && boundedValue[0] == '"' && boundedValue[boundedValue.Length - 1] == '"'
            ? boundedValue
            : "\"" + boundedValue + "\"";
        if (!EntityTagHeaderValue.TryParse(candidate, out EntityTagHeaderValue? parsed) || parsed.IsWeak)
        {
            return false;
        }

        headerValue = parsed.ToString();
        return true;
    }

    private static bool ContainsWhitespace(string value)
    {
        foreach (char character in value)
        {
            if (char.IsWhiteSpace(character))
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryGetSafeRetryAfterHeaderValue(string? value, [NotNullWhen(true)] out string? headerValue)
    {
        headerValue = null;
        if (!TryGetBoundedHeaderValue(value, out string? boundedValue))
        {
            return false;
        }

        if (long.TryParse(boundedValue, NumberStyles.None, CultureInfo.InvariantCulture, out long delaySeconds) && delaySeconds is >= 0 and <= MaxRetryAfterSeconds)
        {
            headerValue = delaySeconds.ToString(CultureInfo.InvariantCulture);
            return true;
        }

        if (DateTimeOffset.TryParseExact(boundedValue, "r", CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out DateTimeOffset retryDate))
        {
            headerValue = retryDate.ToUniversalTime().ToString("r", CultureInfo.InvariantCulture);
            return true;
        }

        return false;
    }

    private static bool IsRetryableGatewayStatusCode(int statusCode)
        => statusCode is StatusCodes.Status409Conflict
            or StatusCodes.Status429TooManyRequests
            or StatusCodes.Status500InternalServerError
            or StatusCodes.Status502BadGateway
            or StatusCodes.Status503ServiceUnavailable;

    private static int NormalizeGatewayExceptionStatusCode(int statusCode, bool includeCommandOnlyStatusCodes)
        => statusCode is StatusCodes.Status400BadRequest
            or StatusCodes.Status401Unauthorized
            or StatusCodes.Status403Forbidden
            or StatusCodes.Status404NotFound
            or StatusCodes.Status429TooManyRequests
            or StatusCodes.Status500InternalServerError
            or StatusCodes.Status501NotImplemented
            or StatusCodes.Status502BadGateway
            or StatusCodes.Status503ServiceUnavailable
            || (includeCommandOnlyStatusCodes && statusCode is StatusCodes.Status409Conflict or StatusCodes.Status422UnprocessableEntity)
                ? statusCode
                : StatusCodes.Status502BadGateway;
}
